import java.net.URI;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * 深度研究模型 qwen-deep-research 示例（DashScope 原生接口）
 * 两步流程：第一步模型反问确认 → 第二步深入研究
 *
 * 运行方式：
 *   export DASHSCOPE_API_KEY="sk-xxx"
 *   javac DeepResearchExample.java && java DeepResearchExample
 */
public class DeepResearchExample {

    static final String BASE_URL =
        "https://{WorkspaceId}.cn-beijing.maas.aliyuncs.com/api/v1/services/aigc/text-generation/generation";
    static final Pattern CONTENT_PATTERN = Pattern.compile("\"content\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"");

    public static void main(String[] args) throws Exception {
        String apiKey = System.getenv("DASHSCOPE_API_KEY");
        if (apiKey == null || apiKey.isEmpty()) {
            System.err.println("请设置环境变量 DASHSCOPE_API_KEY");
            return;
        }

        HttpClient client = HttpClient.newBuilder()
            .connectTimeout(Duration.ofSeconds(30))
            .build();

        // ==================== 第一步：模型反问确认 ====================
        System.out.println("==================== 第一步：模型反问确认 ====================");

        String step1Body = """
            {
                "input": {
                    "messages": [
                        {"role": "user", "content": "研究一下人工智能在教育中的应用"}
                    ]
                },
                "model": "qwen-deep-research"
            }
            """;

        String step1Content = streamCall(client, apiKey, step1Body);

        // ==================== 第二步：深入研究 ====================
        System.out.println("\n\n==================== 第二步：深入研究 ====================");

        String step2Body = String.format("""
            {
                "input": {
                    "messages": [
                        {"role": "user", "content": "研究一下人工智能在教育中的应用"},
                        {"role": "assistant", "content": %s},
                        {"role": "user", "content": "我主要关注个性化学习和智能评估这两个方面"}
                    ]
                },
                "model": "qwen-deep-research"
            }
            """, escapeJson(step1Content));

        streamCall(client, apiKey, step2Body);
        System.out.println();
    }

    static String streamCall(HttpClient client, String apiKey, String requestBody) throws Exception {
        HttpRequest request = HttpRequest.newBuilder()
            .uri(URI.create(BASE_URL))
            .timeout(Duration.ofMinutes(5))
            .header("Content-Type", "application/json")
            .header("Authorization", "Bearer " + apiKey)
            .header("X-DashScope-SSE", "enable")
            .POST(HttpRequest.BodyPublishers.ofString(requestBody))
            .build();

        StringBuilder accumulated = new StringBuilder();

        HttpResponse<java.util.stream.Stream<String>> response =
            client.send(request, HttpResponse.BodyHandlers.ofLines());

        if (response.statusCode() != 200) {
            System.err.println("HTTP " + response.statusCode());
            response.body().forEach(System.err::println);
            return "";
        }

        response.body().forEach(line -> {
            if (line.startsWith("data:")) {
                String json = line.substring(5).trim();
                if (json.isEmpty()) return;
                String content = extractContent(json);
                if (content != null && !content.isEmpty()) {
                    accumulated.append(content);
                    System.out.print(content);
                    System.out.flush();
                }
            }
        });

        return accumulated.toString();
    }

    static String extractContent(String json) {
        Matcher m = CONTENT_PATTERN.matcher(json);
        if (m.find()) {
            return m.group(1)
                .replace("\\n", "\n")
                .replace("\\t", "\t")
                .replace("\\\"", "\"")
                .replace("\\\\", "\\");
        }
        return null;
    }

    static String escapeJson(String s) {
        return "\"" + s
            .replace("\\", "\\\\")
            .replace("\"", "\\\"")
            .replace("\n", "\\n")
            .replace("\r", "\\r")
            .replace("\t", "\\t")
            + "\"";
    }
}
